base=Path('docs/validation/background-103');p=Path('.local/parity-runs/remaining-107');out=Path('docs/validation/full-108-107');out.mkdir(exist_ok=True);(out/'images').mkdir(exist_ok=True)
features=json.loads((base/'features.json').read_text());data=json.loads((base/'adjudicated.json').read_text());derived=json.loads((p/'derived-retained-assertions.json').read_text());rows=data['newJudgments'];by={r['id']:r for r in features};assert len(rows)==len({r['id']for r in rows})==108
checks=[]
for r in rows:
 assert r['state']==by[r['id']]['state'];assert by[r['id']]['fullFeatureCertified'] is False
