 for role in ['VA','CA']:
  d=json.loads((p/f'{role}.{label}.render.json').read_text());image=next(x for x in d['rows']if x['label']=='editor'and x['status']=='captured');src=Path(image['path']);target=out/'images'/f'{role}-{label}.png';shutil.copy2(src,target);visual+=f'<section><b>{role}</b><a href="images/{target.name}"><img src="images/{target.name}"></a></section>'
 visual+='</div>'
